import java.util.*;

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        int n = nums.length;
        Set<String> seen = new HashSet<>();
        List<List<Integer>> ans = new ArrayList<>();

        for (int i = 0; i < n - 2; i++) {
            for (int j = i + 1; j < n - 1; j++) {
                for (int k = j + 1; k < n; k++) {
                    if (nums[i] + nums[j] + nums[k] == 0) {
                        // 三个数排序后再拼 key，保证 [-1,0,1] 和 [1,-1,0] 是同一个 key
                        int[] t = {nums[i], nums[j], nums[k]};
                        Arrays.sort(t);
                        String key = t[0] + "," + t[1] + "," + t[2];
                        if (seen.add(key)) {
                            ans.add(Arrays.asList(t[0], t[1], t[2]));
                        }
                    }
                }
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        List<List<Integer>> ans = new ArrayList<>();

        for (int i = 0; i < n - 2; i++) {
            // 第一个数去重：和前一个相同就别再算了，否则结果里会出现重复三元组
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            // 排序后如果最小的数都大于 0，后面不可能再凑出 0
            if (nums[i] > 0) break;

            Set<Integer> seen = new HashSet<>();
            for (int j = i + 1; j < n; j++) {
                int need = -nums[i] - nums[j];
                if (seen.contains(need)) {
                    ans.add(Arrays.asList(nums[i], need, nums[j]));
                    // 第二个数去重：相同的 nums[j] 只处理一次
                    while (j + 1 < n && nums[j + 1] == nums[j]) j++;
                } else {
                    seen.add(nums[j]);
                }
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        List<List<Integer>> ans = new ArrayList<>();

        for (int i = 0; i < n - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue; // 第一个数去重
            if (nums[i] > 0) break;                        // 最小数都大于 0，无解

            int left = i + 1, right = n - 1;
            while (left < right) {
                int sum = nums[i] + nums[left] + nums[right];
                if (sum == 0) {
                    ans.add(Arrays.asList(nums[i], nums[left], nums[right]));
                    // 跳过重复的左值，否则会重复收集同一组答案
                    while (left < right && nums[left] == nums[left + 1]) left++;
                    while (left < right && nums[right] == nums[right - 1]) right--;
                    left++;
                    right--;
                } else if (sum < 0) {
                    left++;   // 和太小，左指针右移让和变大
                } else {
                    right--;  // 和太大，右指针左移让和变小
                }
            }
        }
        return ans;
    }
}
